CREATE TABLE public.studio_brands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, logo_asset_id uuid, kit jsonb NOT NULL DEFAULT '{"colors":["#080808","#FFFFFF","#C6A15B"],"font":"Inter","tone":"","approved":false}'::jsonb, kit_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.studio_brands TO authenticated; GRANT ALL ON public.studio_brands TO service_role;
ALTER TABLE public.studio_brands ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff manage studio brands" ON public.studio_brands FOR ALL TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.studio_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), brand_id uuid NOT NULL REFERENCES public.studio_brands(id), name text NOT NULL, kind text NOT NULL DEFAULT 'image', storage_path text, external_url text, original_asset_id uuid REFERENCES public.studio_assets(id), approved boolean NOT NULL DEFAULT false, rights_note text NOT NULL DEFAULT '', created_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.studio_assets TO authenticated; GRANT ALL ON public.studio_assets TO service_role;
ALTER TABLE public.studio_assets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff manage studio assets" ON public.studio_assets FOR ALL TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.studio_projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), brand_id uuid NOT NULL REFERENCES public.studio_brands(id), title text NOT NULL DEFAULT 'Untitled project', kind text NOT NULL DEFAULT 'graphic', document jsonb NOT NULL DEFAULT '{}'::jsonb, kit_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb, kit_version integer NOT NULL DEFAULT 1, revision integer NOT NULL DEFAULT 1, archived boolean NOT NULL DEFAULT false, is_template boolean NOT NULL DEFAULT false, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.studio_projects TO authenticated; GRANT ALL ON public.studio_projects TO service_role;
ALTER TABLE public.studio_projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff manage studio projects" ON public.studio_projects FOR ALL TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.studio_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.studio_projects(id), document jsonb NOT NULL, revision integer NOT NULL, title text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,revision));
GRANT SELECT,INSERT ON public.studio_versions TO authenticated; GRANT ALL ON public.studio_versions TO service_role;
ALTER TABLE public.studio_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff read versions" ON public.studio_versions FOR SELECT TO authenticated USING (public.is_staff(auth.uid()));
CREATE POLICY "Staff create versions" ON public.studio_versions FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE TABLE public.studio_exports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.studio_projects(id), status text NOT NULL DEFAULT 'queued', format text NOT NULL, settings jsonb NOT NULL DEFAULT '{}'::jsonb, progress integer NOT NULL DEFAULT 0, storage_path text, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.studio_exports TO authenticated; GRANT ALL ON public.studio_exports TO service_role;
ALTER TABLE public.studio_exports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Staff manage exports" ON public.studio_exports FOR ALL TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
CREATE POLICY "Staff upload studio files" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='media' AND (storage.foldername(name))[1]='studio' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff read studio files" ON storage.objects FOR SELECT TO authenticated USING (bucket_id='media' AND (storage.foldername(name))[1]='studio' AND public.is_staff(auth.uid()));
CREATE POLICY "Staff update studio files" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id='media' AND (storage.foldername(name))[1]='studio' AND public.is_staff(auth.uid())) WITH CHECK (bucket_id='media' AND (storage.foldername(name))[1]='studio' AND public.is_staff(auth.uid()));
CREATE OR REPLACE FUNCTION public.save_studio_project(_id uuid, _document jsonb, _title text, _kind text, _expected_revision integer) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE rev integer; BEGIN UPDATE public.studio_projects SET document=_document,title=left(_title,200),kind=_kind,revision=revision+1,updated_at=now() WHERE id=_id AND revision=_expected_revision RETURNING revision INTO rev; IF rev IS NULL THEN RAISE EXCEPTION 'This project changed elsewhere. Reopen it before saving.'; END IF; RETURN rev; END; $$;
GRANT EXECUTE ON FUNCTION public.save_studio_project(uuid,jsonb,text,text,integer) TO authenticated;